{"command":"cd /tmp/ctest && cat > src/main.rs <<'EOF'
use clap::{Arg, ArgAction, Command};
fn main() {
    let m = Command::new("deadnix")
        .version("1.3.1")
        .about("Find dead code in .nix files")
        .disable_help_flag(true)
        .arg(Arg::new("NO_LAMBDA_ARG").short('l').long("no-lambda-arg").action(ArgAction::SetTrue).help("Don't check lambda parameter arguments"))
        .arg(Arg::new("NO_LAMBDA_PATTERN_NAMES").short('L').long("no-lambda-pattern-names").action(ArgAction::SetTrue).help("Don't check lambda attrset pattern names (don't break nixpkgs callPackage)"))
        .arg(Arg::new("NO_UNDERSCORE").short('_').long("no-underscore").action(ArgAction::SetTrue).help("Don't check any bindings that start with a _\n(Lambda arguments starting with _ are not checked anyway.)"))
        .arg(Arg::new("WARN_USED_UNDERSCORE").short('W').long("warn-used-underscore").action(ArgAction::SetTrue).help("Warn if bindings are referenced that start with '_'"))
        .arg(Arg::new("QUIET").short('q').long("quiet").action(ArgAction::SetTrue).help("Don't print dead code report"))
        .arg(Arg::new("EDIT").short('e').long("edit").action(ArgAction::SetTrue).help("Remove unused code and write to source file"))
        .arg(Arg::new("HIDDEN").short('h').long("hidden").action(ArgAction::SetTrue).help("Recurse into hidden subdirectories and process hidden .*.nix files"))
        .arg(Arg::new("help").long("help").action(ArgAction::Help))
        .arg(Arg::new("FAIL_ON_REPORTS").short('f').long("fail").action(ArgAction::SetTrue).help("Exit with 1 if unused code has been found"))
        .arg(Arg::new("OUTPUT_FORMAT").short('o').long("output-format").value_parser(["human-readable", "json"]).default_value("human-readable").help("Output format to use"))
        .arg(Arg::new("EXCLUDES").long("exclude").num_args(1..).action(ArgAction::Append).help("Files to exclude from analysis"))
        .arg(Arg::new("FILE_PATHS").num_args(0..).default_value(".").help(".nix files, or directories with .nix files inside"))
        .get_matches();
    println!("{:?}", m.get_many::<String>("FILE_PATHS").map(|v| v.collect::<Vec<_>>()));
    println!("{:?}", m.get_many::<String>("EXCLUDES").map(|v| v.collect::<Vec<_>>()));
}
EOF
cargo build --offline 2>&1 | grep -E 'error|warning: unused' ; ./target/debug/ctest --help; ./target/debug/ctest --bogus; ./target/debug/ctest -o yaml; ./target/debug/ctest -o; ./target/debug/ctest --exclude; ./target/debug/ctest --exclude a b -- c d; ./target/debug/ctest -V"}

