//! A lossless concrete syntax tree stored in an arena.

use crate::kinds::SyntaxKind;

pub type NodeId = usize;
pub type TokenId = usize;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Element {
    Node(NodeId),
    Token(TokenId),
}

#[derive(Debug)]
pub struct Node {
    pub kind: SyntaxKind,
    pub start: usize,
    pub end: usize,
    pub parent: Option<NodeId>,
    pub children: Vec<Element>,
}

#[derive(Debug)]
pub struct Token {
    pub kind: SyntaxKind,
    pub start: usize,
    pub end: usize,
    pub parent: NodeId,
}

#[derive(Debug)]
pub struct Tree {
    pub text: String,
    pub nodes: Vec<Node>,
    pub tokens: Vec<Token>,
    pub root: NodeId,
}

impl Tree {
    pub fn node(&self, id: NodeId) -> &Node {
        &self.nodes[id]
    }

    pub fn token(&self, id: TokenId) -> &Token {
        &self.tokens[id]
    }

    pub fn kind(&self, el: Element) -> SyntaxKind {
        match el {
            Element::Node(n) => self.nodes[n].kind,
            Element::Token(t) => self.tokens[t].kind,
        }
    }

    pub fn range(&self, el: Element) -> (usize, usize) {
        match el {
            Element::Node(n) => (self.nodes[n].start, self.nodes[n].end),
            Element::Token(t) => (self.tokens[t].start, self.tokens[t].end),
        }
    }

    pub fn node_text(&self, id: NodeId) -> &str {
        let n = &self.nodes[id];
        &self.text[n.start..n.end]
    }

    pub fn token_text(&self, id: TokenId) -> &str {
        let t = &self.tokens[id];
        &self.text[t.start..t.end]
    }

    pub fn parent_of(&self, el: Element) -> Option<NodeId> {
        match el {
            Element::Node(n) => self.nodes[n].parent,
            Element::Token(t) => Some(self.tokens[t].parent),
        }
    }

    /// Child nodes (skipping tokens).
    pub fn child_nodes(&self, id: NodeId) -> impl Iterator<Item = NodeId> + '_ {
        self.nodes[id].children.iter().filter_map(|c| match c {
            Element::Node(n) => Some(*n),
            Element::Token(_) => None,
        })
    }

    /// Child tokens (skipping nodes).
    pub fn child_tokens(&self, id: NodeId) -> impl Iterator<Item = TokenId> + '_ {
        self.nodes[id].children.iter().filter_map(|c| match c {
            Element::Token(t) => Some(*t),
            Element::Node(_) => None,
        })
    }

    pub fn first_child_node_of_kind(&self, id: NodeId, kind: SyntaxKind) -> Option<NodeId> {
        self.child_nodes(id).find(|n| self.nodes[*n].kind == kind)
    }

    pub fn has_child_token(&self, id: NodeId, kind: SyntaxKind) -> bool {
        self.child_tokens(id).any(|t| self.tokens[t].kind == kind)
    }

    /// Index of an element within its parent's children.
    pub fn index_in_parent(&self, el: Element) -> Option<(NodeId, usize)> {
        let parent = self.parent_of(el)?;
        let idx = self.nodes[parent].children.iter().position(|c| *c == el)?;
        Some((parent, idx))
    }

    pub fn prev_sibling_or_token(&self, el: Element) -> Option<Element> {
        let (parent, idx) = self.index_in_parent(el)?;
        if idx == 0 {
            None
        } else {
            Some(self.nodes[parent].children[idx - 1])
        }
    }

    pub fn next_sibling_or_token(&self, el: Element) -> Option<Element> {
        let (parent, idx) = self.index_in_parent(el)?;
        self.nodes[parent].children.get(idx + 1).copied()
    }

    /// First token inside an element (in document order).
    pub fn first_token(&self, el: Element) -> Option<TokenId> {
        match el {
            Element::Token(t) => Some(t),
            Element::Node(n) => {
                for c in &self.nodes[n].children {
                    if let Some(t) = self.first_token(*c) {
                        return Some(t);
                    }
                }
                None
            }
        }
    }

    /// Last token inside an element (in document order).
    pub fn last_token(&self, el: Element) -> Option<TokenId> {
        match el {
            Element::Token(t) => Some(t),
            Element::Node(n) => {
                for c in self.nodes[n].children.iter().rev() {
                    if let Some(t) = self.last_token(*c) {
                        return Some(t);
                    }
                }
                None
            }
        }
    }

    /// The token immediately preceding the given token in document order.
    pub fn prev_token(&self, tok: TokenId) -> Option<TokenId> {
        let mut el = Element::Token(tok);
        loop {
            if let Some(prev) = self.prev_sibling_or_token(el) {
                if let Some(t) = self.last_token(prev) {
                    return Some(t);
                }
                // empty node; keep moving left
                el = prev;
                continue;
            }
            let parent = self.parent_of(el)?;
            el = Element::Node(parent);
        }
    }

    /// All descendant nodes in pre-order, including the node itself.
    pub fn descendants(&self, id: NodeId) -> Vec<NodeId> {
        let mut out = Vec::new();
        let mut stack = vec![id];
        while let Some(n) = stack.pop() {
            out.push(n);
            for c in self.nodes[n].children.iter().rev() {
                if let Element::Node(cn) = c {
                    stack.push(*cn);
                }
            }
        }
        out
    }

    pub fn ancestors(&self, id: NodeId) -> impl Iterator<Item = NodeId> + '_ {
        let mut cur = self.nodes[id].parent;
        std::iter::from_fn(move || {
            let c = cur?;
            cur = self.nodes[c].parent;
            Some(c)
        })
    }

    /// For NODE_IDENT: the identifier text.
    pub fn ident_name(&self, id: NodeId) -> &str {
        self.node_text(id)
    }
}
