//! Tokenizer for the Nix language.

use crate::kinds::SyntaxKind::{self, *};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum IdentType {
    Path,
    Store,
    Uri,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Context {
    StringBody { multiline: bool },
    StringEnd,
    Interpol { brackets: u32 },
    InterpolStart,
    Path,
}

fn is_valid_path_char(c: char) -> bool {
    matches!(c, 'a'..='z' | 'A'..='Z' | '0'..='9' | '/' | '_' | '.' | '+' | '-')
}

fn is_valid_uri_char(c: char) -> bool {
    match c {
        '%' | '?' | ':' | '@' | '&' | '=' | '$' | ',' | '!' | '~' | '*' | '\'' => true,
        c => is_valid_path_char(c),
    }
}

fn is_ident_start(c: char) -> bool {
    matches!(c, 'a'..='z' | 'A'..='Z' | '_')
}

fn is_ident_char(c: char) -> bool {
    matches!(c, 'a'..='z' | 'A'..='Z' | '0'..='9' | '_' | '-' | '\'')
}

pub struct Tokenizer<'a> {
    input: &'a str,
    pos: usize,
    ctx: Vec<Context>,
}

impl<'a> Tokenizer<'a> {
    pub fn new(input: &'a str) -> Self {
        Tokenizer {
            input,
            pos: 0,
            ctx: Vec::new(),
        }
    }

    fn remaining(&self) -> &'a str {
        &self.input[self.pos..]
    }

    fn peek(&self) -> Option<char> {
        self.remaining().chars().next()
    }

    fn peek_at(&self, n: usize) -> Option<char> {
        self.remaining().chars().nth(n)
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek()?;
        self.pos += c.len_utf8();
        Some(c)
    }

    fn starts_with_bump(&mut self, s: &str) -> bool {
        if self.remaining().starts_with(s) {
            self.pos += s.len();
            true
        } else {
            false
        }
    }

    fn consume<F: Fn(char) -> bool>(&mut self, f: F) -> usize {
        let mut len = 0;
        while let Some(c) = self.peek() {
            if !f(c) {
                break;
            }
            self.pos += c.len_utf8();
            len += 1;
        }
        len
    }

    fn str_since(&self, start: usize) -> &'a str {
        &self.input[start..self.pos]
    }

    fn next_string(&mut self, multiline: bool) -> SyntaxKind {
        loop {
            self.consume(|c| c != '"' && c != '\\' && c != '$' && c != '\'');
            match self.peek() {
                None => return TOKEN_ERROR,
                Some('"') if !multiline => {
                    self.ctx.pop();
                    self.ctx.push(Context::StringEnd);
                    return TOKEN_STRING_CONTENT;
                }
                Some('"') => {
                    self.next();
                }
                Some('\\') if !multiline => {
                    self.next();
                    if self.next().is_none() {
                        return TOKEN_ERROR;
                    }
                }
                Some('\\') => {
                    self.next();
                }
                Some('\'') if multiline => {
                    if self.remaining().starts_with("''") {
                        match self.peek_at(2) {
                            Some('\'') => {
                                // ''' => escaped ''
                                self.next();
                                self.next();
                                self.next();
                            }
                            Some('$') => {
                                // ''$ => escaped $
                                self.next();
                                self.next();
                                self.next();
                            }
                            Some('\\') => {
                                // ''\x => escaped x
                                self.next();
                                self.next();
                                self.next();
                                if self.next().is_none() {
                                    return TOKEN_ERROR;
                                }
                            }
                            _ => {
                                self.ctx.pop();
                                self.ctx.push(Context::StringEnd);
                                return TOKEN_STRING_CONTENT;
                            }
                        }
                    } else {
                        self.next();
                    }
                }
                Some('\'') => {
                    self.next();
                }
                Some('$') => {
                    if self.remaining().starts_with("${") {
                        self.ctx.push(Context::InterpolStart);
                        return TOKEN_STRING_CONTENT;
                    } else {
                        self.next();
                    }
                }
                Some(_) => unreachable!(),
            }
        }
    }

    fn next_inner(&mut self) -> Option<SyntaxKind> {
        let start = self.pos;

        loop {
            match self.ctx.last().copied() {
                Some(Context::InterpolStart) => {
                    self.ctx.pop();
                    self.ctx.push(Context::Interpol { brackets: 0 });
                    if self.starts_with_bump("${") {
                        return Some(TOKEN_INTERPOL_START);
                    } else {
                        // Should not happen; treat as error
                        self.next();
                        return Some(TOKEN_ERROR);
                    }
                }
                Some(Context::Path) => {
                    if self.remaining().starts_with("${") {
                        self.ctx.push(Context::InterpolStart);
                        continue;
                    } else if self.peek().map_or(false, is_valid_path_char) {
                        self.consume(is_valid_path_char);
                        if !self.remaining().starts_with("${") {
                            self.ctx.pop();
                        }
                        return Some(TOKEN_PATH);
                    } else {
                        self.ctx.pop();
                    }
                }
                Some(Context::StringBody { multiline }) => {
                    let token = self.next_string(multiline);
                    if self.pos == start {
                        // Empty content: move on to the next context (string end / interpolation)
                        continue;
                    }
                    return Some(token);
                }
                Some(Context::StringEnd) => {
                    self.ctx.pop();
                    let status = match self.peek() {
                        Some('"') => {
                            self.next();
                            true
                        }
                        Some('\'') => {
                            self.next();
                            match self.peek() {
                                Some('\'') => {
                                    self.next();
                                    true
                                }
                                _ => false,
                            }
                        }
                        _ => false,
                    };
                    return Some(if status { TOKEN_STRING_END } else { TOKEN_ERROR });
                }
                _ => break,
            }
        }

        if self.consume(char::is_whitespace) > 0 {
            return Some(TOKEN_WHITESPACE);
        }

        if self.peek() == Some('#') {
            self.consume(|c| c != '\n');
            return Some(TOKEN_COMMENT);
        }
        if self.starts_with_bump("/*") {
            loop {
                self.consume(|c| c != '*');
                self.next();
                match self.peek() {
                    None => return Some(TOKEN_ERROR),
                    Some('/') => {
                        self.next();
                        return Some(TOKEN_COMMENT);
                    }
                    _ => (),
                }
            }
        }

        if self.starts_with_bump("...") {
            return Some(TOKEN_ELLIPSIS);
        }

        // Check if it's a path
        let store_path = self.peek() == Some('<');
        let kind = {
            let skipped: String = self
                .remaining()
                .chars()
                .take_while(|&c| match c {
                    '<' | '/' => store_path,
                    _ => is_valid_path_char(c),
                })
                .collect();
            let mut lookahead = self.remaining().chars().skip(skipped.chars().count());
            match (lookahead.next(), lookahead.next()) {
                // a//b parses as Update(a, b)
                (Some('/'), Some('/')) => None,
                (Some('/'), Some('*')) => None,
                (Some('/'), Some(c)) if !c.is_whitespace() => Some(IdentType::Path),
                (Some('>'), _) => Some(IdentType::Store),
                (Some(':'), Some(c)) if is_valid_uri_char(c) && !skipped.is_empty() => {
                    Some(IdentType::Uri)
                }
                _ => None,
            }
        };

        let c = self.next()?;

        if c == '~' || kind == Some(IdentType::Path) {
            if c == '~' && self.next() != Some('/') {
                return Some(TOKEN_ERROR);
            }
            self.consume(is_valid_path_char);
            if self.remaining().starts_with("${") {
                self.ctx.push(Context::Path);
            }
            return Some(TOKEN_PATH);
        }

        Some(match c {
            '=' if self.peek() == Some('=') => {
                self.next();
                TOKEN_EQUAL
            }
            '!' if self.peek() == Some('=') => {
                self.next();
                TOKEN_NOT_EQUAL
            }
            '!' => TOKEN_INVERT,
            '{' => {
                if let Some(Context::Interpol { brackets }) = self.ctx.last_mut() {
                    *brackets += 1;
                }
                TOKEN_L_BRACE
            }
            '}' => {
