            '=' if self.peek() == Some('=') => {
                self.next();
                TOKEN_EQUAL
            }
            '!' if self.peek() == Some('=') => {
                self.next();
                TOKEN_NOT_EQUAL
            }
            '!' => TOKEN_INVERT,
            '{' => {
                if let Some(Context::Interpol { brackets }) = self.ctx.last_mut() {
                    *brackets += 1;
                }
