//! Recursive-descent parser producing a lossless syntax tree.

use std::collections::VecDeque;
use std::fmt;

use crate::kinds::SyntaxKind::{self, *};
use crate::lexer::tokenize;
use crate::tree::{Element, Node, NodeId, Token, Tree};

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ParseError {
    Unexpected(usize, usize),
    UnexpectedExtra(usize, usize),
    UnexpectedWanted(SyntaxKind, usize, usize, Vec<SyntaxKind>),
    UnexpectedDoubleBind(usize, usize),
    UnexpectedEOF,
    UnexpectedEOFWanted(Vec<SyntaxKind>),
    RecursionLimitExceeded,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::Unexpected(s, e) => write!(f, "unexpected token at {}..{}", s, e),
            ParseError::UnexpectedExtra(s, e) => write!(f, "unexpected token at {}..{}", s, e),
            ParseError::UnexpectedWanted(kind, s, e, wanted) => {
                write!(f, "unexpected {:?} at {}..{}, wanted any of {:?}", kind, s, e, wanted)
            }
            ParseError::UnexpectedDoubleBind(s, e) => {
                write!(f, "unexpected double bind at {}..{}", s, e)
            }
            ParseError::UnexpectedEOF => write!(f, "unexpected end of file"),
            ParseError::UnexpectedEOFWanted(wanted) => {
                write!(f, "unexpected end of file, wanted any of {:?}", wanted)
            }
            ParseError::RecursionLimitExceeded => write!(f, "recursion limit exceeded"),
        }
    }
}

const MAX_DEPTH: u32 = 512;

#[derive(Clone, Copy)]
struct Checkpoint {
    depth: usize,
    child_idx: usize,
}

struct OpenNode {
    kind: SyntaxKind,
    children: Vec<Element>,
}

struct Parser {
    text: String,
    buffer: VecDeque<(SyntaxKind, usize, usize)>,
    trivia_buffer: Vec<(SyntaxKind, usize, usize)>,
    consumed: usize,
    nodes: Vec<Node>,
    tokens: Vec<Token>,
    stack: Vec<OpenNode>,
    errors: Vec<ParseError>,
    depth: u32,
}

impl Parser {
    fn new(text: &str) -> Self {
        let toks = tokenize(text);
        Parser {
            text: text.to_string(),
            buffer: toks.into_iter().collect(),
            trivia_buffer: Vec::new(),
            consumed: 0,
            nodes: Vec::new(),
            tokens: Vec::new(),
            stack: Vec::new(),
            errors: Vec::new(),
            depth: 0,
        }
    }

    // ---------- tree building ----------

    fn emit_token(&mut self, kind: SyntaxKind, start: usize, end: usize) {
        let id = self.tokens.len();
        self.tokens.push(Token {
            kind,
            start,
            end,
            parent: usize::MAX,
        });
        self.stack
            .last_mut()
            .expect("no open node")
            .children
            .push(Element::Token(id));
        self.consumed = end;
    }

    fn drain_trivia_buffer(&mut self) {
        let trivia = std::mem::take(&mut self.trivia_buffer);
        for (kind, start, end) in trivia {
            self.emit_token(kind, start, end);
        }
    }

    fn start_node(&mut self, kind: SyntaxKind) {
        self.drain_trivia_buffer();
        self.stack.push(OpenNode {
            kind,
            children: Vec::new(),
        });
    }

    fn checkpoint(&mut self) -> Checkpoint {
        self.drain_trivia_buffer();
        let top = self.stack.last().expect("no open node");
        Checkpoint {
            depth: self.stack.len(),
            child_idx: top.children.len(),
        }
    }

    fn start_node_at(&mut self, cp: Checkpoint, kind: SyntaxKind) {
        assert_eq!(cp.depth, self.stack.len(), "checkpoint depth mismatch");
        let top = self.stack.last_mut().expect("no open node");
        let moved = top.children.split_off(cp.child_idx);
        self.stack.push(OpenNode {
            kind,
            children: moved,
        });
    }

    fn finish_node(&mut self) -> (usize, usize) {
        let open = self.stack.pop().expect("no open node");
        let id = self.nodes.len();
        // compute range
        let (start, end) = {
            let mut start = None;
            let mut end = None;
            for c in &open.children {
                let (s, e) = match c {
                    Element::Node(n) => (self.nodes[*n].start, self.nodes[*n].end),
                    Element::Token(t) => (self.tokens[*t].start, self.tokens[*t].end),
                };
                if start.is_none() {
                    start = Some(s);
                }
                end = Some(e);
            }
            match (start, end) {
                (Some(s), Some(e)) => (s, e),
                _ => (self.consumed, self.consumed),
            }
        };
        for c in &open.children {
            match c {
                Element::Node(n) => self.nodes[*n].parent = Some(id),
                Element::Token(t) => self.tokens[*t].parent = id,
            }
        }
        self.nodes.push(Node {
            kind: open.kind,
            start,
            end,
            parent: None,
            children: open.children,
        });
        if let Some(parent) = self.stack.last_mut() {
            parent.children.push(Element::Node(id));
        }
        (start, end)
    }

    // ---------- token access ----------

    fn peek_raw(&self) -> Option<SyntaxKind> {
        self.buffer.front().map(|t| t.0)
    }

    fn peek(&mut self) -> Option<SyntaxKind> {
        while let Some(&(kind, s, e)) = self.buffer.front() {
            if kind.is_trivia() {
                self.trivia_buffer.push((kind, s, e));
                self.buffer.pop_front();
            } else {
                break;
            }
        }
        self.peek_raw()
    }

    /// Peek at the non-trivia tokens ahead, without consuming anything.
    fn lookahead_kinds(&self, n: usize) -> Vec<SyntaxKind> {
        self.buffer
            .iter()
            .map(|t| t.0)
            .filter(|k| !k.is_trivia())
            .take(n)
            .collect()
    }

    fn bump(&mut self) {
        self.drain_trivia_buffer();
        match self.buffer.pop_front() {
            Some((kind, s, e)) => {
                self.emit_token(kind, s, e);
            }
            None => self.errors.push(ParseError::UnexpectedEOF),
        }
    }

    fn start_error_node(&mut self) -> usize {
        self.start_node(NODE_ERROR);
        self.consumed
    }

    fn finish_error_node(&mut self) -> usize {
        self.finish_node();
        self.consumed
    }

    fn expect_peek_any(&mut self, allowed: &[SyntaxKind]) -> Option<SyntaxKind> {
        let next = match self.peek() {
            None => None,
            Some(kind) if allowed.contains(&kind) => Some(kind),
            Some(kind) => {
                let start = self.start_error_node();
                loop {
                    self.bump();
                    if self
                        .peek()
                        .map(|k| allowed.contains(&k))
                        .unwrap_or(true)
                    {
                        break;
                    }
                }
                let end = self.finish_error_node();
                self.errors.push(ParseError::UnexpectedWanted(
                    kind,
                    start,
                    end,
                    allowed.to_vec(),
                ));
                self.peek()
            }
        };
        if next.is_none() {
            self.errors
                .push(ParseError::UnexpectedEOFWanted(allowed.to_vec()));
        }
        next
    }

    fn expect(&mut self, expected: SyntaxKind) {
        if self.expect_peek_any(&[expected]).is_some() {
            self.bump();
        }
    }

    fn expect_ident(&mut self) {
        self.start_node(NODE_IDENT);
        if self.expect_peek_any(&[TOKEN_IDENT, TOKEN_OR]).is_some() {
            self.bump();
        }
        self.finish_node();
    }

    // ---------- grammar ----------

    fn parse_dynamic(&mut self) {
        self.start_node(NODE_DYNAMIC);
        self.bump();
        self.parse_expr();
        self.expect(TOKEN_INTERPOL_END);
        self.finish_node();
    }

    fn parse_string(&mut self) {
        self.start_node(NODE_STRING);
        self.expect(TOKEN_STRING_START);
        loop {
            match self.expect_peek_any(&[
                TOKEN_STRING_END,
                TOKEN_STRING_CONTENT,
                TOKEN_INTERPOL_START,
            ]) {
                Some(TOKEN_STRING_CONTENT) => self.bump(),
                Some(TOKEN_INTERPOL_START) => {
                    self.start_node(NODE_INTERPOL);
                    self.bump();
                    self.parse_expr();
                    self.expect(TOKEN_INTERPOL_END);
                    self.finish_node();
                }
                _ => break,
            }
        }
        self.expect(TOKEN_STRING_END);
        self.finish_node();
    }

    fn parse_attr(&mut self) {
        match self.peek() {
            Some(TOKEN_INTERPOL_START) => self.parse_dynamic(),
            Some(TOKEN_STRING_START) => self.parse_string(),
            _ => self.expect_ident(),
        }
    }

    fn parse_attrpath(&mut self) {
        self.start_node(NODE_ATTRPATH);
        loop {
            self.parse_attr();
            if self.peek() == Some(TOKEN_DOT) {
                self.bump();
            } else {
                break;
            }
        }
        self.finish_node();
    }

    fn parse_pattern(&mut self, bound: bool) {
        self.expect(TOKEN_L_BRACE);
        loop {
            match self.peek() {
                Some(TOKEN_R_BRACE) => {
                    self.bump();
                    break;
                }
                Some(TOKEN_ELLIPSIS) => {
                    self.bump();
                    self.expect(TOKEN_R_BRACE);
                    break;
                }
                Some(TOKEN_IDENT) => {
                    self.start_node(NODE_PAT_ENTRY);
                    self.expect_ident();
                    if self.peek() == Some(TOKEN_QUESTION) {
                        self.bump();
                        self.parse_expr();
                    }
                    self.finish_node();
                    match self.peek() {
                        Some(TOKEN_COMMA) => self.bump(),
                        _ => {
                            self.expect(TOKEN_R_BRACE);
                            break;
                        }
                    }
                }
                None => {
                    self.errors.push(ParseError::UnexpectedEOF);
                    break;
                }
                Some(_) => {
                    // Skip unexpected tokens until something sensible
                    match self.expect_peek_any(&[TOKEN_R_BRACE, TOKEN_ELLIPSIS, TOKEN_IDENT]) {
                        None => break,
                        Some(_) => continue,
                    }
                }
            }
        }

        if self.peek() == Some(TOKEN_AT) {
            let kind = if bound { NODE_ERROR } else { NODE_PAT_BIND };
            self.start_node(kind);
            let start = self.consumed;
            self.bump();
            self.expect_ident();
            let (_, end) = self.finish_node();
            if bound {
                self.errors
                    .push(ParseError::UnexpectedDoubleBind(start, end));
            }
        }
    }

    fn parse_set(&mut self, until: SyntaxKind) {
        loop {
            match self.peek() {
                None => {
                    self.errors.push(ParseError::UnexpectedEOF);
                    break;
                }
                Some(t) if t == until => {
                    self.bump();
                    break;
                }
                Some(TOKEN_INHERIT) => {
                    self.start_node(NODE_INHERIT);
                    self.bump();
                    if self.peek() == Some(TOKEN_L_PAREN) {
                        self.start_node(NODE_INHERIT_FROM);
                        self.bump();
                        self.parse_expr();
                        self.expect(TOKEN_R_PAREN);
                        self.finish_node();
                    }
                    loop {
                        match self.peek() {
                            Some(TOKEN_IDENT) | Some(TOKEN_OR) => self.expect_ident(),
                            Some(TOKEN_STRING_START) => self.parse_string(),
                            Some(TOKEN_INTERPOL_START) => self.parse_dynamic(),
                            _ => break,
                        }
                    }
                    self.expect(TOKEN_SEMICOLON);
                    self.finish_node();
                }
                Some(_) => {
                    self.start_node(NODE_ATTRPATH_VALUE);
                    self.parse_attrpath();
                    self.expect(TOKEN_ASSIGN);
                    self.parse_expr();
                    self.expect(TOKEN_SEMICOLON);
                    self.finish_node();
                }
            }
        }
    }

    fn parse_val(&mut self) -> Checkpoint {
        let checkpoint = self.checkpoint();
        match self.peek() {
            Some(TOKEN_L_PAREN) => {
                self.start_node(NODE_PAREN);
                self.bump();
                self.parse_expr();
                self.bump();
                self.finish_node();
            }
            Some(TOKEN_REC) => {
                self.start_node(NODE_ATTR_SET);
                self.bump();
                self.expect(TOKEN_L_BRACE);
                self.parse_set(TOKEN_R_BRACE);
                self.finish_node();
            }
            Some(TOKEN_L_BRACE) => {
                // Lookahead to decide between a pattern and an attribute set
                let la = self.lookahead_kinds(4);
                let is_pattern = match (la.get(1).copied(), la.get(2).copied()) {
                    (Some(TOKEN_IDENT), Some(TOKEN_COMMA)) => true,
                    (Some(TOKEN_IDENT), Some(TOKEN_QUESTION)) => true,
                    (Some(TOKEN_IDENT), Some(TOKEN_R_BRACE)) => matches!(
                        la.get(3).copied(),
                        Some(TOKEN_COLON) | Some(TOKEN_AT)
                    ),
                    (Some(TOKEN_ELLIPSIS), _) => true,
                    (Some(TOKEN_R_BRACE), Some(TOKEN_COLON)) => true,
                    (Some(TOKEN_R_BRACE), Some(TOKEN_AT)) => true,
                    _ => false,
                };
                if is_pattern {
                    self.start_node(NODE_LAMBDA);
                    self.start_node(NODE_PATTERN);
                    self.parse_pattern(false);
                    self.finish_node();
                    self.expect(TOKEN_COLON);
                    self.parse_expr();
                    self.finish_node();
                } else {
                    self.start_node(NODE_ATTR_SET);
                    self.bump();
                    self.parse_set(TOKEN_R_BRACE);
                    self.finish_node();
                }
            }
            Some(TOKEN_L_BRACK) => {
                self.start_node(NODE_LIST);
                self.bump();
                while self.peek().map(|t| t != TOKEN_R_BRACK).unwrap_or(false) {
                    self.parse_select();
                }
                self.bump();
                self.finish_node();
            }
            Some(TOKEN_STRING_START) => self.parse_string(),
            Some(TOKEN_PATH) => {
                self.start_node(NODE_PATH);
                self.bump();
                loop {
                    match self.peek_raw() {
                        Some(TOKEN_PATH) => self.bump(),
                        Some(TOKEN_INTERPOL_START) => {
                            self.start_node(NODE_INTERPOL);
                            self.bump();
                            self.parse_expr();
                            self.expect(TOKEN_INTERPOL_END);
                            self.finish_node();
                        }
                        _ => break,
                    }
                }
                self.finish_node();
            }
            Some(TOKEN_URI) | Some(TOKEN_FLOAT) | Some(TOKEN_INTEGER) => {
                self.start_node(NODE_LITERAL);
                self.bump();
                self.finish_node();
            }
            Some(TOKEN_IDENT) => {
                self.start_node(NODE_IDENT);
                self.bump();
                self.finish_node();
                match self.peek() {
                    Some(TOKEN_COLON) => {
                        self.start_node_at(checkpoint, NODE_LAMBDA);
                        // Wrap the identifier in an IDENT_PARAM node for clarity
                        self.bump();
                        self.parse_expr();
                        self.finish_node();
                    }
                    Some(TOKEN_AT) => {
                        self.start_node_at(checkpoint, NODE_LAMBDA);
                        self.start_node_at(checkpoint, NODE_PATTERN);
                        self.start_node_at(checkpoint, NODE_PAT_BIND);
                        self.bump();
                        self.finish_node();
                        self.parse_pattern(true);
                        self.finish_node();
                        self.expect(TOKEN_COLON);
                        self.parse_expr();
                        self.finish_node();
                    }
                    _ => (),
                }
            }
            Some(kind) => {
                let start = self.start_error_node();
                self.bump();
                let end = self.finish_error_node();
                self.errors.push(ParseError::UnexpectedWanted(
                    kind,
                    start,
                    end,
                    vec![
                        TOKEN_L_PAREN,
                        TOKEN_REC,
                        TOKEN_L_BRACE,
                        TOKEN_L_BRACK,
                        TOKEN_STRING_START,
                        TOKEN_IDENT,
                    ],
                ));
            }
            None => {
                self.errors.push(ParseError::UnexpectedEOF);
            }
        }
        checkpoint
    }

    fn parse_select(&mut self) -> Checkpoint {
        let checkpoint = self.parse_val();
        if self.peek() == Some(TOKEN_DOT) {
            self.start_node_at(checkpoint, NODE_SELECT);
            self.bump();
            self.parse_attrpath();
            if self.peek() == Some(TOKEN_OR) {
                self.bump();
                self.parse_val();
            }
            self.finish_node();
        }
        checkpoint
    }

    fn parse_fn(&mut self) -> Checkpoint {
        let checkpoint = self.parse_select();
        while self.peek().map(|t| t.is_fn_arg()).unwrap_or(false) {
            self.start_node_at(checkpoint, NODE_APPLY);
            if self.peek() == Some(TOKEN_OR) {
                self.start_node(NODE_IDENT);
                self.bump();
                self.finish_node();
            } else {
                self.parse_select();
            }
            self.finish_node();
        }
        checkpoint
    }

    fn parse_negate(&mut self) -> Checkpoint {
        if self.peek() == Some(TOKEN_SUB) {
            let checkpoint = self.checkpoint();
            self.start_node(NODE_UNARY_OP);
            self.bump();
            self.parse_negate();
            self.finish_node();
            checkpoint
        } else {
            self.parse_fn()
        }
    }

    fn parse_hasattr(&mut self) -> Checkpoint {
        let checkpoint = self.parse_negate();
        while self.peek() == Some(TOKEN_QUESTION) {
            self.start_node_at(checkpoint, NODE_HAS_ATTR);
            self.bump();
            self.parse_attrpath();
            self.finish_node();
        }
        checkpoint
    }

    fn parse_left_assoc(
        &mut self,
        next: fn(&mut Parser) -> Checkpoint,
        ops: &[SyntaxKind],
    ) -> Checkpoint {
        let checkpoint = next(self);
        while self.peek().map(|t| ops.contains(&t)).unwrap_or(false) {
            self.start_node_at(checkpoint, NODE_BIN_OP);
            self.bump();
            next(self);
            self.finish_node();
        }
        checkpoint
    }

    fn parse_right_assoc(
        &mut self,
        next: fn(&mut Parser) -> Checkpoint,
        this: fn(&mut Parser) -> Checkpoint,
        ops: &[SyntaxKind],
    ) -> Checkpoint {
        let checkpoint = next(self);
        if self.peek().map(|t| ops.contains(&t)).unwrap_or(false) {
            self.start_node_at(checkpoint, NODE_BIN_OP);
            self.bump();
            this(self);
            self.finish_node();
        }
        checkpoint
    }

    fn parse_non_assoc(
        &mut self,
        next: fn(&mut Parser) -> Checkpoint,
        ops: &[SyntaxKind],
    ) -> Checkpoint {
        let checkpoint = next(self);
        if self.peek().map(|t| ops.contains(&t)).unwrap_or(false) {
            self.start_node_at(checkpoint, NODE_BIN_OP);
            self.bump();
            next(self);
            self.finish_node();
        }
        checkpoint
    }

    fn parse_mul(&mut self) -> Checkpoint {
        self.parse_left_assoc(Parser::parse_hasattr, &[TOKEN_MUL, TOKEN_DIV])
    }

    fn parse_add(&mut self) -> Checkpoint {
        self.parse_left_assoc(Parser::parse_mul, &[TOKEN_ADD, TOKEN_SUB])
    }

    fn parse_concat(&mut self) -> Checkpoint {
        self.parse_right_assoc(Parser::parse_add, Parser::parse_concat, &[TOKEN_CONCAT])
    }

    fn parse_invert(&mut self) -> Checkpoint {
        if self.peek() == Some(TOKEN_INVERT) {
            let checkpoint = self.checkpoint();
            self.start_node(NODE_UNARY_OP);
            self.bump();
            self.parse_invert();
            self.finish_node();
            checkpoint
        } else {
            self.parse_concat()
        }
    }

    fn parse_update(&mut self) -> Checkpoint {
        self.parse_right_assoc(Parser::parse_invert, Parser::parse_update, &[TOKEN_UPDATE])
    }

    fn parse_compare(&mut self) -> Checkpoint {
        self.parse_non_assoc(
            Parser::parse_update,
            &[TOKEN_LESS, TOKEN_LESS_OR_EQ, TOKEN_MORE, TOKEN_MORE_OR_EQ],
        )
    }

    fn parse_equality(&mut self) -> Checkpoint {
        self.parse_non_assoc(Parser::parse_compare, &[TOKEN_EQUAL, TOKEN_NOT_EQUAL])
    }

    fn parse_and(&mut self) -> Checkpoint {
        self.parse_left_assoc(Parser::parse_equality, &[TOKEN_AND_AND])
    }

    fn parse_or(&mut self) -> Checkpoint {
        self.parse_left_assoc(Parser::parse_and, &[TOKEN_OR_OR])
    }

    fn parse_implication(&mut self) -> Checkpoint {
        self.parse_right_assoc(
            Parser::parse_or,
            Parser::parse_implication,
            &[TOKEN_IMPLICATION],
        )
    }

    fn parse_pipe(&mut self) -> Checkpoint {
        self.parse_left_assoc(
            Parser::parse_implication,
            &[TOKEN_PIPE_RIGHT, TOKEN_PIPE_LEFT],
        )
    }

    fn parse_math(&mut self) -> Checkpoint {
        self.parse_pipe()
    }

    fn parse_expr(&mut self) -> Checkpoint {
        self.depth += 1;
        if self.depth > MAX_DEPTH {
            self.errors.push(ParseError::RecursionLimitExceeded);
            let checkpoint = self.checkpoint();
            self.start_error_node();
            while self.peek().is_some() {
                self.bump();
            }
            self.finish_error_node();
            self.depth -= 1;
            return checkpoint;
        }
        let out = match self.peek() {
            Some(TOKEN_LET) => {
                let checkpoint = self.checkpoint();
                self.bump();
                if self.peek() == Some(TOKEN_L_BRACE) {
                    self.start_node_at(checkpoint, NODE_LEGACY_LET);
                    self.bump();
                    self.parse_set(TOKEN_R_BRACE);
                    self.finish_node();
                } else {
                    self.start_node_at(checkpoint, NODE_LET_IN);
                    self.parse_set(TOKEN_IN);
                    self.parse_expr();
                    self.finish_node();
                }
                checkpoint
            }
            Some(TOKEN_WITH) => {
                let checkpoint = self.checkpoint();
                self.start_node(NODE_WITH);
                self.bump();
                self.parse_expr();
                self.expect(TOKEN_SEMICOLON);
                self.parse_expr();
                self.finish_node();
                checkpoint
            }
            Some(TOKEN_IF) => {
                let checkpoint = self.checkpoint();
                self.start_node(NODE_IF_ELSE);
                self.bump();
                self.parse_expr();
                self.expect(TOKEN_THEN);
                self.parse_expr();
                self.expect(TOKEN_ELSE);
                self.parse_expr();
                self.finish_node();
                checkpoint
            }
            Some(TOKEN_ASSERT) => {
                let checkpoint = self.checkpoint();
                self.start_node(NODE_ASSERT);
                self.bump();
                self.parse_expr();
                self.expect(TOKEN_SEMICOLON);
                self.parse_expr();
                self.finish_node();
                checkpoint
            }
            _ => self.parse_math(),
        };
        self.depth -= 1;
        out
    }
}

pub struct Parse {
    pub tree: Tree,
    pub errors: Vec<ParseError>,
}

pub fn parse(text: &str) -> Parse {
    let mut p = Parser::new(text);
    p.start_node(NODE_ROOT);
    p.parse_expr();
    // Drain trailing trivia into the root
    p.peek();
    if p.peek().is_some() {
        let start = p.start_error_node();
        while p.peek().is_some() {
            p.bump();
        }
        let end = p.finish_error_node();
        p.errors.push(ParseError::UnexpectedExtra(start, end));
    }
    p.drain_trivia_buffer();
    p.finish_node();
    let root = p.nodes.len() - 1;
    Parse {
        tree: Tree {
            text: p.text,
            nodes: p.nodes,
            tokens: p.tokens,
            root,
        },
        errors: p.errors,
    }
}
