struct Checkpoint(usize);

struct Parser {
    text: String,
    buffer: VecDeque<(SyntaxKind, usize, usize)>,
    trivia_buffer: Vec<(SyntaxKind, usize, usize)>,
    consumed: usize,
    nodes: Vec<Node>,
    tokens: Vec<Token>,
    /// Flat list of pending children (rowan-style builder).
    children: Vec<Element>,
    /// Open nodes: (kind, index of first child in `children`).
    parents: Vec<(SyntaxKind, usize)>,
    errors: Vec<ParseError>,
    depth: u32,
}

impl Parser {
    fn new(text: &str) -> Self {
        let toks = tokenize(text);
        Parser {
            text: text.to_string(),
            buffer: toks.into_iter().collect(),
            trivia_buffer: Vec::new(),
            consumed: 0,
            nodes: Vec::new(),
            tokens: Vec::new(),
            children: Vec::new(),
            parents: Vec::new(),
            errors: Vec::new(),
            depth: 0,
        }
    }

    // ---------- tree building ----------

    fn emit_token(&mut self, kind: SyntaxKind, start: usize, end: usize) {
        let id = self.tokens.len();
        self.tokens.push(Token {
            kind,
            start,
            end,
            parent: usize::MAX,
        });
        self.children.push(Element::Token(id));
        self.consumed = end;
    }

    fn drain_trivia_buffer(&mut self) {
        let trivia = std::mem::take(&mut self.trivia_buffer);
        for (kind, start, end) in trivia {
            self.emit_token(kind, start, end);
        }
    }

    fn start_node(&mut self, kind: SyntaxKind) {
        self.drain_trivia_buffer();
        self.parents.push((kind, self.children.len()));
    }

    fn checkpoint(&mut self) -> Checkpoint {
        self.drain_trivia_buffer();
        Checkpoint(self.children.len())
    }

    fn start_node_at(&mut self, cp: Checkpoint, kind: SyntaxKind) {
        assert!(cp.0 <= self.children.len(), "checkpoint no longer valid");
        if let Some(&(_, first_child)) = self.parents.last() {
            assert!(cp.0 >= first_child, "checkpoint no longer valid");
        }
        self.parents.push((kind, cp.0));
    }

    fn finish_node(&mut self) -> (usize, usize) {
        let (kind, first) = self.parents.pop().expect("no open node");
        let node_children = self.children.split_off(first);
        let id = self.nodes.len();
        let (start, end) = {
            let mut start = None;
            let mut end = None;
            for c in &node_children {
                let (s, e) = match c {
                    Element::Node(n) => (self.nodes[*n].start, self.nodes[*n].end),
                    Element::Token(t) => (self.tokens[*t].start, self.tokens[*t].end),
                };
                if start.is_none() {
                    start = Some(s);
                }
                end = Some(e);
            }
            match (start, end) {
                (Some(s), Some(e)) => (s, e),
                _ => (self.consumed, self.consumed),
            }
        };
        for c in &node_children {
            match c {
                Element::Node(n) => self.nodes[*n].parent = Some(id),
                Element::Token(t) => self.tokens[*t].parent = id,
            }
        }
        self.nodes.push(Node {
            kind,
            start,
            end,
            parent: None,
            children: node_children,
        });
        self.children.push(Element::Node(id));
        (start, end)
    }

