//! Scopes and bindings in a Nix syntax tree.

use crate::kinds::SyntaxKind::{self, *};
use crate::tree::{NodeId, Tree};

#[derive(Clone, Copy, PartialEq, Eq, Debug, Hash)]
pub enum BindingKind {
    LambdaArg,
    LambdaPatternEntry,
    LambdaPatternBind,
    LetBinding,
}

impl BindingKind {
    pub fn is_lambda_pattern(self) -> bool {
        matches!(
            self,
            BindingKind::LambdaPatternEntry | BindingKind::LambdaPatternBind
        )
    }
}

#[derive(Clone, Debug)]
pub struct Binding {
    /// The NODE_IDENT holding the name.
    pub name: NodeId,
    /// Node containing the declaration; identifiers inside it are not usages of itself.
    pub decl: NodeId,
    /// Node searched for usages of sibling bindings (e.g. the value of a `let` entry).
    pub value: Option<NodeId>,
    pub kind: BindingKind,
    /// Whether this binding may be reported as dead.
    pub mortal: bool,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ScopeKind {
    LambdaArg,
    LambdaPattern,
    LetIn,
    RecAttrSet,
}

#[derive(Clone, Debug)]
pub struct Scope {
    pub node: NodeId,
    pub kind: ScopeKind,
    pub bindings: Vec<Binding>,
    pub body: Option<NodeId>,
}

/// Is this an attribute set with the `rec` keyword?
pub fn is_rec_attrset(tree: &Tree, node: NodeId) -> bool {
    tree.node(node).kind == NODE_ATTR_SET && tree.has_child_token(node, TOKEN_REC)
}

/// The identifier of an attrpath-value entry (first attribute if it is an identifier).
pub fn attrpath_value_ident(tree: &Tree, entry: NodeId) -> Option<NodeId> {
    let attrpath = tree.first_child_node_of_kind(entry, NODE_ATTRPATH)?;
    let first = tree.child_nodes(attrpath).next()?;
    if tree.node(first).kind == NODE_IDENT {
        Some(first)
    } else {
        None
    }
}

/// The `from` expression node of an inherit (`inherit (expr) ...`).
pub fn inherit_from(tree: &Tree, inherit: NodeId) -> Option<NodeId> {
    tree.first_child_node_of_kind(inherit, NODE_INHERIT_FROM)
}

/// Identifier attributes of an inherit entry.
pub fn inherit_idents(tree: &Tree, inherit: NodeId) -> Vec<NodeId> {
    tree.child_nodes(inherit)
        .filter(|n| tree.node(*n).kind == NODE_IDENT)
        .collect()
}

/// All attribute nodes of an inherit entry (identifiers, strings, dynamics).
pub fn inherit_attrs(tree: &Tree, inherit: NodeId) -> Vec<NodeId> {
    tree.child_nodes(inherit)
        .filter(|n| {
            matches!(
                tree.node(*n).kind,
                NODE_IDENT | NODE_STRING | NODE_DYNAMIC
            )
        })
        .collect()
}

/// Entries (attrpath-values and inherits) of a let-in or attribute set.
pub fn entries(tree: &Tree, node: NodeId) -> Vec<NodeId> {
    tree.child_nodes(node)
        .filter(|n| {
            matches!(
                tree.node(*n).kind,
                NODE_ATTRPATH_VALUE | NODE_INHERIT
            )
        })
        .collect()
}

/// The body expression of a let-in (the expression after `in`).
pub fn let_in_body(tree: &Tree, let_in: NodeId) -> Option<NodeId> {
    let mut seen_in = false;
    for child in &tree.node(let_in).children {
        match child {
            crate::tree::Element::Token(t) => {
                if tree.token(*t).kind == TOKEN_IN {
                    seen_in = true;
                }
            }
            crate::tree::Element::Node(n) => {
                if seen_in {
                    return Some(*n);
                }
            }
        }
    }
    None
}

/// The parameter node of a lambda (NODE_IDENT or NODE_PATTERN) and its body.
pub fn lambda_parts(tree: &Tree, lambda: NodeId) -> (Option<NodeId>, Option<NodeId>) {
    let mut nodes = tree.child_nodes(lambda);
    let param = nodes.next();
    let mut body = None;
    let mut seen_colon = false;
    for child in &tree.node(lambda).children {
        match child {
            crate::tree::Element::Token(t) => {
                if tree.token(*t).kind == TOKEN_COLON {
                    seen_colon = true;
                }
            }
            crate::tree::Element::Node(n) => {
                if seen_colon && body.is_none() {
                    body = Some(*n);
                }
            }
        }
    }
    (param, body)
}

fn entry_bindings(tree: &Tree, node: NodeId, mortal: bool, out: &mut Vec<Binding>) {
    for entry in entries(tree, node) {
        match tree.node(entry).kind {
            NODE_ATTRPATH_VALUE => {
                if let Some(ident) = attrpath_value_ident(tree, entry) {
                    out.push(Binding {
                        name: ident,
                        decl: entry,
                        value: Some(entry),
                        kind: BindingKind::LetBinding,
                        mortal,
                    });
                }
            }
            NODE_INHERIT => {
                let from = inherit_from(tree, entry);
                for ident in inherit_idents(tree, entry) {
                    out.push(Binding {
                        name: ident,
                        decl: ident,
                        value: from,
                        kind: BindingKind::LetBinding,
                        mortal,
                    });
                }
            }
            _ => {}
        }
    }
}

impl Scope {
    /// Create a scope for the given node, if the node introduces one.
    pub fn new(tree: &Tree, node: NodeId) -> Option<Scope> {
        match tree.node(node).kind {
            NODE_LAMBDA => {
                let (param, body) = lambda_parts(tree, node);
                let param = param?;
                match tree.node(param).kind {
                    NODE_IDENT => Some(Scope {
                        node,
                        kind: ScopeKind::LambdaArg,
                        bindings: vec![Binding {
                            name: param,
                            decl: param,
                            value: None,
                            kind: BindingKind::LambdaArg,
                            mortal: true,
                        }],
                        body,
                    }),
                    NODE_PATTERN => {
                        let mut bindings = Vec::new();
                        for child in tree.child_nodes(param) {
                            match tree.node(child).kind {
                                NODE_PAT_ENTRY => {
                                    if let Some(ident) = tree
                                        .child_nodes(child)
                                        .find(|n| tree.node(*n).kind == NODE_IDENT)
                                    {
                                        bindings.push(Binding {
                                            name: ident,
                                            decl: child,
                                            value: Some(child),
                                            kind: BindingKind::LambdaPatternEntry,
                                            mortal: true,
                                        });
                                    }
                                }
                                NODE_PAT_BIND => {
                                    if let Some(ident) = tree
                                        .child_nodes(child)
                                        .find(|n| tree.node(*n).kind == NODE_IDENT)
                                    {
                                        bindings.push(Binding {
                                            name: ident,
                                            decl: child,
                                            value: None,
                                            kind: BindingKind::LambdaPatternBind,
                                            mortal: true,
                                        });
                                    }
                                }
                                _ => {}
                            }
                        }
                        Some(Scope {
                            node,
                            kind: ScopeKind::LambdaPattern,
                            bindings,
                            body,
                        })
                    }
                    _ => None,
                }
            }
            NODE_LET_IN => {
                let mut bindings = Vec::new();
                entry_bindings(tree, node, true, &mut bindings);
                Some(Scope {
                    node,
                    kind: ScopeKind::LetIn,
                    bindings,
                    body: let_in_body(tree, node),
                })
            }
            NODE_ATTR_SET if is_rec_attrset(tree, node) => {
                let mut bindings = Vec::new();
                entry_bindings(tree, node, false, &mut bindings);
                Some(Scope {
                    node,
                    kind: ScopeKind::RecAttrSet,
                    bindings,
                    body: None,
                })
            }
            _ => None,
        }
    }

    /// Does this scope declare the given name?
    pub fn binds(&self, tree: &Tree, name: &str) -> bool {
        self.bindings
            .iter()
            .any(|b| tree.ident_name(b.name) == name)
    }
}

/// Is this node kind potentially a scope?
pub fn may_be_scope(kind: SyntaxKind) -> bool {
    matches!(kind, NODE_LAMBDA | NODE_LET_IN | NODE_ATTR_SET)
}
