//! Searching for usages of identifiers.

use crate::kinds::SyntaxKind::*;
use crate::scope::{inherit_from, inherit_idents, may_be_scope, Scope};
use crate::tree::{NodeId, Tree};

/// Does `node` (or any of its descendants) reference `name`, ignoring anything
/// inside `exclude` and respecting shadowing by inner scopes?
pub fn find_usage(tree: &Tree, name: &str, node: NodeId, exclude: Option<(usize, usize)>) -> bool {
    let n = tree.node(node);
    if let Some((s, e)) = exclude {
        if n.start >= s && n.end <= e && !(n.start == n.end && (n.start == s || n.start == e) && s != e && false) {
            // node fully inside the excluded range
            if n.start >= s && n.end <= e {
                return false;
            }
        }
    }
    match n.kind {
        NODE_IDENT => tree.ident_name(node) == name,
        NODE_ATTRPATH => tree
            .child_nodes(node)
            .filter(|c| tree.node(*c).kind != NODE_IDENT)
            .any(|c| find_usage(tree, name, c, exclude)),
        kind if may_be_scope(kind) => {
            match Scope::new(tree, node) {
                Some(scope) if scope.binds(tree, name) => {
                    // Shadowed. Only `inherit` entries directly in this scope may still
                    // refer to the outer binding.
                    for child in tree.child_nodes(node) {
                        if tree.node(child).kind != NODE_INHERIT {
                            continue;
                        }
                        match inherit_from(tree, child) {
                            Some(from) => {
                                if find_usage(tree, name, from, exclude) {
                                    return true;
                                }
                            }
                            None => {
                                for ident in inherit_idents(tree, child) {
                                    if tree.ident_name(ident) == name {
                                        return true;
                                    }
                                }
                            }
                        }
                    }
                    false
                }
                _ => tree
                    .child_nodes(node)
                    .any(|c| find_usage(tree, name, c, exclude)),
            }
        }
        _ => tree
            .child_nodes(node)
            .any(|c| find_usage(tree, name, c, exclude)),
    }
}
