//! Dead code detection.

use std::collections::HashMap;

use crate::kinds::SyntaxKind::*;
use crate::scope::{may_be_scope, Binding, BindingKind, Scope};
use crate::tree::{Element, NodeId, Tree};
use crate::usage::find_usage;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ResultKind {
    Unused,
    UsedUnderscore,
}

#[derive(Clone, Debug)]
pub struct DeadCode {
    pub binding: Binding,
    /// Scope node that owns this binding.
    pub scope_node: NodeId,
    pub result: ResultKind,
}

impl DeadCode {
    pub fn name<'a>(&self, tree: &'a Tree) -> &'a str {
        tree.ident_name(self.binding.name)
    }

    pub fn message(&self, tree: &Tree) -> String {
        let what = match self.binding.kind {
            BindingKind::LambdaArg => "lambda argument",
            BindingKind::LambdaPatternEntry | BindingKind::LambdaPatternBind => "lambda pattern",
            BindingKind::LetBinding => "let binding",
        };
        let prefix = match self.result {
            ResultKind::Unused => "Unused",
            ResultKind::UsedUnderscore => "Used",
        };
        format!("{} {}: {}", prefix, what, self.name(tree))
    }

    /// Byte range of the identifier.
    pub fn range(&self, tree: &Tree) -> (usize, usize) {
        let n = tree.node(self.binding.name);
        (n.start, n.end)
    }
}

