fn is_skipped(tree: &Tree, binding: &Binding) -> bool {
    let first = match tree.first_token(Element::Node(binding.name)) {
        Some(t) => t,
        None => return false,
    };
    let mut newlines = 0usize;
    let mut tok = tree.prev_token(first);
    while let Some(t) = tok {
        match tree.token(t).kind {
            TOKEN_WHITESPACE => {
                newlines += tree.token_text(t).matches('\n').count();
                if newlines > 1 {
                    return false;
                }
            }
            TOKEN_COMMENT => {
                if tree.token_text(t).contains("deadnix: skip") {
                    return true;
                }
            }
            _ => {}
        }
        tok = tree.prev_token(t);
    }
    false
}

fn is_checked(tree: &Tree, binding: &Binding, settings: &Settings) -> bool {
    if !binding.mortal {
        return false;
    }
    let name = tree.ident_name(binding.name);
    match binding.kind {
        BindingKind::LambdaArg => {
            if settings.no_lambda_arg || name.starts_with('_') {
                return false;
            }
        }
        BindingKind::LambdaPatternEntry => {
            if settings.no_lambda_pattern_names {
                return false;
            }
            if settings.no_underscore && name.starts_with('_') {
                return false;
            }
        }
        BindingKind::LambdaPatternBind | BindingKind::LetBinding => {
            if settings.no_underscore && name.starts_with('_') {
                return false;
            }
        }
    }
    !is_skipped(tree, binding)
}

fn is_used(tree: &Tree, scope: &Scope, binding: &Binding, results: &HashMap<NodeId, ResultKind>) -> bool {
    let name = tree.ident_name(binding.name);
    let decl = tree.node(binding.decl);
    let exclude = Some((decl.start, decl.end));
    for other in &scope.bindings {
        if results.contains_key(&other.name) {
            continue;
        }
        if let Some(value) = other.value {
            if find_usage(tree, name, value, exclude) {
                return true;
            }
        }
    }
    if let Some(body) = scope.body {
        if find_usage(tree, name, body, exclude) {
            return true;
        }
    }
    false
}

pub fn find_dead_code(tree: &Tree, settings: &Settings) -> Vec<DeadCode> {
    // Collect all scopes in document order
