        .descendants(tree.root)
        .into_iter()
        .filter(|n| may_be_scope(tree.node(*n).kind))
        .filter_map(|n| Scope::new(tree, n))
        .collect();

    // Which bindings to check at all
    let checked: Vec<Vec<bool>> = scopes
        .iter()
        .map(|s| {
            s.bindings
                .iter()
                .map(|b| is_checked(tree, b, settings))
                .collect()
        })
        .collect();

    let mut results: HashMap<NodeId, ResultKind> = HashMap::new();
    let mut prev_len = 0usize;
    loop {
        for (si, scope) in scopes.iter().enumerate() {
            for (bi, binding) in scope.bindings.iter().enumerate() {
                if !checked[si][bi] {
                    continue;
                }
                if results.get(&binding.name) == Some(&ResultKind::Unused) {
                    continue;
                }
                if !is_used(tree, scope, binding, &results) {
                    results.insert(binding.name, ResultKind::Unused);
                } else if settings.warn_used_underscore
                    && binding.kind != BindingKind::LambdaArg
                    && tree.ident_name(binding.name).starts_with('_')
                {
                    results.insert(binding.name, ResultKind::UsedUnderscore);
                }
            }
        }
        if results.len() == prev_len {
            break;
        }
        prev_len = results.len();
    }

    let mut out = Vec::new();
    for scope in &scopes {
        for binding in &scope.bindings {
            if let Some(kind) = results.get(&binding.name) {
                out.push(DeadCode {
                    binding: binding.clone(),
                    scope_node: scope.node,
                    result: *kind,
                });
            }
        }
    }
    out.sort_by_key(|d| tree.node(d.binding.name).start);
    out
}
