//! Human-readable (ariadne-like) and JSON reports.

use std::fmt::Write as _;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Color {
    Red,
    Yellow,
    Magenta,
    Cyan,
    Fixed(u8),
}

impl Color {
    fn code(self) -> String {
        match self {
            Color::Red => "31".to_string(),
            Color::Yellow => "33".to_string(),
            Color::Magenta => "35".to_string(),
            Color::Cyan => "36".to_string(),
            Color::Fixed(n) => format!("38;5;{}", n),
        }
    }
}

fn paint(out: &mut String, text: &str, color: Option<Color>, enabled: bool) {
    match (color, enabled) {
        (Some(c), true) => {
            let _ = write!(out, "\x1b[{}m{}\x1b[0m", c.code(), text);
        }
        _ => out.push_str(text),
    }
}

fn paint_char(out: &mut String, c: char, color: Option<Color>, enabled: bool) {
    let mut buf = [0u8; 4];
    let s = c.encode_utf8(&mut buf);
    paint(out, s, color, enabled);
}

pub struct Label {
    /// Byte range in the source.
    pub start: usize,
    pub end: usize,
    pub message: String,
    pub color: Color,
}

struct Line {
    /// Offset in chars.
    offset: usize,
    /// Length in chars, including the line terminator.
    len: usize,
    /// Line content without trailing whitespace.
    chars: String,
}

struct Source {
    lines: Vec<Line>,
    /// Total length in chars.
    len: usize,
}

impl Source {
    fn new(text: &str) -> Source {
        let mut lines: Vec<Line> = Vec::new();
        let mut offset = 0usize;
        // (line, ends_with_cr)
        let mut last_line: Option<(Line, bool)> = None;
        let terminators = ['\r', '\n', '\x0B', '\x0C', '\u{0085}', '\u{2028}', '\u{2029}'];
        for piece in text.split_inclusive(terminators) {
            if let Some((last, ends_with_cr)) = last_line.as_mut() {
                if *ends_with_cr && piece == "\n" {
                    last.len += 1;
                    offset += 1;
                    continue;
                }
            }
            let len = piece.chars().count();
            let ends_with_cr = piece.ends_with('\r');
            let line = Line {
                offset,
                len,
                chars: piece.trim_end().to_owned(),
            };
            offset += len;
            if let Some((l, _)) = last_line.replace((line, ends_with_cr)) {
                lines.push(l);
            }
        }
        if let Some((l, _)) = last_line {
            lines.push(l);
        }
        Source { lines, len: offset }
    }

    /// (line index, column) for a char offset.
    fn get_offset_line(&self, offset: usize) -> Option<(usize, usize)> {
        if offset <= self.len {
            let idx = match self.lines.binary_search_by_key(&offset, |l| l.offset) {
                Ok(i) => i,
                Err(i) => i.saturating_sub(1),
            };
            let line = self.lines.get(idx)?;
            Some((idx, offset - line.offset))
        } else {
            None
        }
    }

    fn get_line_range(&self, start: usize, end: usize) -> (usize, usize) {
        let s = self.get_offset_line(start).map_or(0, |(l, _)| l);
        let e = self
            .get_offset_line(end.saturating_sub(1).max(start))
            .map_or(self.lines.len(), |(l, _)| l + 1);
        (s, e)
    }
}

fn char_width(c: char, col: usize) -> (char, usize) {
    const TAB_WIDTH: usize = 4;
    match c {
        '\t' => {
            let tab_end = (col / TAB_WIDTH + 1) * TAB_WIDTH;
            (' ', tab_end - col)
        }
        c if c.is_whitespace() => (' ', 1),
        _ => (c, 1),
    }
}

struct CharLabel<'a> {
    start: usize,
    end: usize,
    label: &'a Label,
}

struct LineLabel<'a> {
    col: usize,
    label: &'a CharLabel<'a>,
}

const MARGIN_COLOR: Color = Color::Fixed(246);
const SKIPPED_MARGIN_COLOR: Color = Color::Fixed(240);
const UNIMPORTANT_COLOR: Color = Color::Fixed(249);

const HBAR: char = '─';
const VBAR: char = '│';
const LTOP: char = '╭';
const LBOT: char = '╰';
const LBOX: char = '[';
const RBOX: char = ']';

/// Render a report in the style of a compact ariadne report.
///
/// `location` is the byte offset used for the header location.
pub fn render_human(
    file_name: &str,
    text: &str,
    message: &str,
    labels: &[Label],
    location: usize,
    color: bool,
) -> String {
    let mut out = String::new();
    let src = Source::new(text);

    // Header
    paint(&mut out, "Warning:", Some(Color::Yellow), color);
    let _ = writeln!(out, " {}", message);

    if labels.is_empty() {
        return out;
    }

    // Convert byte spans to char spans
    let char_labels: Vec<CharLabel> = labels
        .iter()
        .map(|l| CharLabel {
            start: text[..l.start.min(text.len())].chars().count(),
            end: text[..l.end.min(text.len())].chars().count(),
            label: l,
        })
        .collect();

    let span_start = char_labels.iter().map(|l| l.start).min().unwrap();
    let span_end = char_labels.iter().map(|l| l.end).max().unwrap();
    let (range_start, range_end) = src.get_line_range(span_start, span_end);

    let line_no_width = (1..)
        .map(|x| 10u64.pow(x))
        .take_while(|x| range_end as u64 / x != 0)
        .count()
        + 1;

    // File name & reference
    let (line_no, col_no) = match src.get_offset_line(location) {
        Some((idx, col)) => (format!("{}", idx + 1), format!("{}", col + 1)),
        None => ("?".to_string(), "?".to_string()),
    };
    out.push_str(&" ".repeat(line_no_width + 2));
    paint_char(&mut out, LTOP, Some(MARGIN_COLOR), color);
    paint_char(&mut out, HBAR, Some(MARGIN_COLOR), color);
    paint_char(&mut out, LBOX, Some(MARGIN_COLOR), color);
    out.push_str(file_name);
    let _ = write!(out, ":{}:{}", line_no, col_no);
    paint_char(&mut out, RBOX, Some(MARGIN_COLOR), color);
    out.push('\n');

    for idx in range_start..range_end {
        let line = match src.lines.get(idx) {
            Some(l) => l,
            None => continue,
        };
        let line_start = line.offset;
        let line_end = line.offset + line.len;

        let mut line_labels: Vec<LineLabel> = char_labels
            .iter()
            .filter(|l| l.start >= line_start && l.end <= line_end)
            .map(|l| LineLabel {
                col: ((l.start + l.end) / 2).max(l.start) - line_start,
                label: l,
            })
            .collect();

        if line_labels.is_empty() {
            continue;
        }

        // Rows are drawn right-to-left
        line_labels.sort_by(|a, b| b.col.cmp(&a.col));

        let arrow_len = line_labels
            .iter()
            .fold(0, |acc, ll| acc.max(ll.label.end.saturating_sub(line_start)))
            + 1;

        let get_vbar = |col: usize, row: usize| -> Option<&LineLabel> {
            line_labels
                .iter()
                .enumerate()
                .find(|(j, ll)| ll.col == col && row <= *j)
                .map(|(_, ll)| ll)
        };

        let get_highlight = |col: usize| -> Option<&CharLabel> {
            let pos = line_start + col;
            line_labels
                .iter()
                .map(|ll| ll.label)
                .filter(|l| l.start <= pos && pos < l.end)
                .min_by_key(|l| l.end - l.start)
        };

        // Margin for the source line
        out.push(' ');
        let line_no = format!("{}", idx + 1);
        let margin = format!(
            "{}{} {}",
            " ".repeat(line_no_width - line_no.chars().count()),
            line_no,
            VBAR
        );
        paint(&mut out, &margin, Some(MARGIN_COLOR), color);

        // Source line
        for (col, c) in line.chars.chars().enumerate() {
            let hl = get_highlight(col).map(|l| l.label.color).unwrap_or(UNIMPORTANT_COLOR);
            let (c, width) = char_width(c, col);
            if c.is_whitespace() {
                for _ in 0..width {
                    paint_char(&mut out, ' ', Some(hl), color);
                }
            } else {
                paint_char(&mut out, c, Some(hl), color);
            }
        }
        out.push('\n');

        // Arrows
        for row in 0..line_labels.len() {
            let line_label = &line_labels[row];
            let lcolor = line_label.label.label.color;

            out.push(' ');
            let margin = format!("{}{}", " ".repeat(line_no_width + 1), VBAR);
            paint(&mut out, &margin, Some(SKIPPED_MARGIN_COLOR), color);

            let mut chars = line.chars.chars();
            for col in 0..arrow_len {
                let width = chars.next().map_or(1, |c| char_width(c, col).1);
                let is_hbar = col > line_label.col;

                let (c, c_color, tail, tail_color): (char, Option<Color>, char, Option<Color>) =
                    if col == line_label.col {
                        (LBOT, Some(lcolor), HBAR, Some(lcolor))
                    } else if let Some(vbar_ll) = get_vbar(col, row) {
                        if is_hbar {
                            (HBAR, Some(lcolor), HBAR, Some(lcolor))
                        } else {
                            (VBAR, Some(vbar_ll.label.label.color), ' ', Some(lcolor))
                        }
                    } else if is_hbar {
                        (HBAR, Some(lcolor), HBAR, Some(lcolor))
                    } else {
                        (' ', None, ' ', None)
                    };

                if width > 0 {
                    paint_char(&mut out, c, c_color, color);
                }
                for _ in 1..width {
                    paint_char(&mut out, tail, tail_color, color);
                }
            }
            let _ = write!(out, " {}", line_label.label.label.message);
            out.push('\n');
        }
    }

    out
}

/// Escape a string as a JSON string literal (serde_json compatible).
pub fn json_string(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0C}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                let _ = write!(out, "\\u{:04x}", c as u32);
            }
