//! Removal of dead code from source text.

use std::collections::{HashMap, HashSet};

use crate::dead::DeadCode;
use crate::kinds::SyntaxKind::*;
use crate::scope::{attrpath_value_ident, entries, inherit_attrs, let_in_body, BindingKind};
use crate::tree::{Element, NodeId, Tree};

/// A text edit: replace the byte range `start..end` with `replacement`.
pub type Edit = (usize, usize, String);

/// Apply the edits (sorted by start) to the source text.
pub fn apply_edits(src: &str, mut edits: Vec<Edit>) -> String {
    edits.sort_by_key(|e| e.0);
    let mut result = String::with_capacity(src.len());
    let mut pos = 0usize;
    for (start, end, replacement) in edits {
        if end <= pos {
            result.push_str(&src[pos..start]);
            continue;
        }
        result.push_str(&src[pos..start]);
        result.push_str(&replacement);
        pos = end;
    }
    result.push_str(&src[pos..]);
    result
}

fn is_ws(tree: &Tree, el: Element) -> bool {
    matches!(el, Element::Token(t) if tree.token(t).kind == TOKEN_WHITESPACE)
}

fn is_token(tree: &Tree, el: Element, kind: crate::kinds::SyntaxKind) -> bool {
    matches!(el, Element::Token(t) if tree.token(t).kind == kind)
}

/// Range of a node extended to include a directly preceding whitespace token.
fn with_preceding_ws(tree: &Tree, node: NodeId) -> (usize, usize) {
    let n = tree.node(node);
    let mut start = n.start;
    if let Some(prev) = tree.prev_sibling_or_token(Element::Node(node)) {
        if is_ws(tree, prev) {
            start = tree.range(prev).0;
        }
    }
    (start, n.end)
}

fn pat_entry_edit(tree: &Tree, entry: NodeId) -> Edit {
    let n = tree.node(entry);
    let el = Element::Node(entry);
    let mut start = n.start;
    let mut end = n.end;

    // Preceding whitespace
    let mut prev = tree.prev_sibling_or_token(el);
    if let Some(p) = prev {
        if is_ws(tree, p) {
            start = tree.range(p).0;
            prev = tree.prev_sibling_or_token(p);
        }
    }

    // Following comma (possibly after whitespace)
    let mut next = tree.next_sibling_or_token(el);
    if let Some(nx) = next {
        if is_ws(tree, nx) {
            next = tree.next_sibling_or_token(nx);
        }
    }
    match next {
        Some(nx) if is_token(tree, nx, TOKEN_COMMA) => {
            end = tree.range(nx).1;
        }
        _ => {
            // Otherwise remove the preceding comma
            if let Some(p) = prev {
                if is_token(tree, p, TOKEN_COMMA) {
                    start = tree.range(p).0;
                }
            }
        }
    }
    (start, end, String::new())
}

fn pat_bind_edit(tree: &Tree, bind: NodeId) -> Edit {
    let n = tree.node(bind);
    let el = Element::Node(bind);
    let mut start = n.start;
    let mut end = n.end;
    if let Some(p) = tree.prev_sibling_or_token(el) {
        if is_ws(tree, p) {
            start = tree.range(p).0;
        }
    }
    if let Some(nx) = tree.next_sibling_or_token(el) {
        if is_ws(tree, nx) {
            end = tree.range(nx).1;
        }
    }
    (start, end, String::new())
}

/// Compute the edits removing the given dead code.
pub fn edits_for(tree: &Tree, dead: &[DeadCode]) -> Vec<Edit> {
    let dead_names: HashSet<NodeId> = dead.iter().map(|d| d.binding.name).collect();
    let mut edits: Vec<Edit> = Vec::new();

    // Let bindings are handled per scope
    let mut let_scopes: HashMap<NodeId, Vec<&DeadCode>> = HashMap::new();
    let mut let_order: Vec<NodeId> = Vec::new();

    for d in dead {
        match d.binding.kind {
            BindingKind::LambdaArg => {
                let (s, e) = d.range(tree);
                edits.push((s, e, format!("_{}", d.name(tree))));
            }
            BindingKind::LambdaPatternEntry => {
                edits.push(pat_entry_edit(tree, d.binding.decl));
            }
            BindingKind::LambdaPatternBind => {
                edits.push(pat_bind_edit(tree, d.binding.decl));
            }
            BindingKind::LetBinding => {
                if !let_scopes.contains_key(&d.scope_node) {
                    let_order.push(d.scope_node);
                }
                let_scopes.entry(d.scope_node).or_default().push(d);
            }
        }
    }

    for scope_node in let_order {
        let scope_dead = &let_scopes[&scope_node];
        let entry_nodes = entries(tree, scope_node);

        // Is anything still alive in this let?
        let mut alive = false;
        for entry in &entry_nodes {
            match tree.node(*entry).kind {
                NODE_ATTRPATH_VALUE => match attrpath_value_ident(tree, *entry) {
                    Some(ident) if dead_names.contains(&ident) => {}
                    _ => alive = true,
                },
                NODE_INHERIT => {
                    for attr in inherit_attrs(tree, *entry) {
                        if tree.node(attr).kind != NODE_IDENT || !dead_names.contains(&attr) {
                            alive = true;
                        }
                    }
                }
                _ => alive = true,
            }
        }

        if !alive && tree.node(scope_node).kind == NODE_LET_IN {
            if let Some(body) = let_in_body(tree, scope_node) {
                let start = tree.node(scope_node).start;
                let end = tree.node(body).start;
                edits.push((start, end, String::new()));
                continue;
            }
        }

        let mut handled_inherits: HashSet<NodeId> = HashSet::new();
        for d in scope_dead {
            let decl = d.binding.decl;
            match tree.node(decl).kind {
                NODE_ATTRPATH_VALUE => {
                    let (s, e) = with_preceding_ws(tree, decl);
                    edits.push((s, e, String::new()));
                }
                NODE_IDENT => {
                    // inherit attribute
                    let inherit = match tree.node(decl).parent {
                        Some(p) => p,
                        None => continue,
                    };
                    let attrs = inherit_attrs(tree, inherit);
                    let all_dead = attrs
                        .iter()
                        .all(|a| tree.node(*a).kind == NODE_IDENT && dead_names.contains(a));
                    if all_dead {
                        if handled_inherits.insert(inherit) {
                            let (s, e) = with_preceding_ws(tree, inherit);
                            edits.push((s, e, String::new()));
                        }
                    } else {
                        let (s, e) = with_preceding_ws(tree, decl);
                        edits.push((s, e, String::new()));
                    }
                }
                _ => {}
            }
        }
    }

    edits
}
