            Err(e) => {
                eprintln!("Error stating file {}: {}", path, e);
            }
            Ok(meta) => {
                if meta.is_dir() {
                    walk_dir(Path::new(path), &options, &mut found);
                } else {
                    found |= process_file(Path::new(path), &options);
                }
            }
        }
    }

    if options.fail_on_reports && found {
        exit(1);
    }
}

/// Error produced while walking a directory (mirrors the shape of walkdir's error).
struct WalkError {
    depth: usize,
    path: PathBuf,
    err: std::io::Error,
}

impl fmt::Debug for WalkError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "Error {{ depth: {}, inner: Io {{ path: Some({:?}), err: {:?} }} }}",
            self.depth, self.path, self.err
        )
    }
}

fn is_hidden(name: &str) -> bool {
    name.starts_with('.') && name != "." && name != ".."
}

fn root_file_name(path: &Path) -> String {
    match path.file_name() {
        Some(n) => n.to_string_lossy().into_owned(),
        None => path.to_string_lossy().into_owned(),
    }
}

fn is_excluded(path: &Path, options: &Options) -> bool {
    if options.excludes.is_empty() {
        return false;
    }
    match fs::canonicalize(path) {
        Ok(p) => options.excludes.iter().any(|e| *e == p),
        Err(_) => false,
    }
}

fn entry_allowed(path: &Path, name: &str, options: &Options) -> bool {
    (options.hidden || !is_hidden(name)) && !is_excluded(path, options)
}

fn walk_dir(root: &Path, options: &Options, found: &mut bool) {
    if !entry_allowed(root, &root_file_name(root), options) {
        return;
    }
    walk_dir_inner(root, 0, options, found);
}

fn walk_dir_inner(dir: &Path, depth: usize, options: &Options, found: &mut bool) {
    let read = fs::read_dir(dir).map_err(|err| WalkError {
        depth,
        path: dir.to_path_buf(),
        err,
    });
    let read = read.unwrap();
    for entry in read {
        let entry = match entry {
            Ok(e) => e,
            Err(err) => {
                let r: Result<(), WalkError> = Err(WalkError {
                    depth: depth + 1,
                    path: dir.to_path_buf(),
                    err,
                });
                r.unwrap();
                continue;
            }
        };
        let path = entry.path();
        let name = entry.file_name().to_string_lossy().into_owned();
        if !entry_allowed(&path, &name, options) {
            continue;
        }
        let file_type = match entry.file_type() {
            Ok(t) => t,
            Err(_) => continue,
        };
        if file_type.is_dir() {
            walk_dir_inner(&path, depth + 1, options, found);
        } else if file_type.is_file() && has_nix_extension(&path) {
            *found |= process_file(&path, options);
        }
    }
}

fn has_nix_extension(path: &Path) -> bool {
    path.extension()
        .map(|e| e.to_string_lossy().eq_ignore_ascii_case("nix"))
        .unwrap_or(false)
}

fn label_color(kind: BindingKind) -> Color {
    match kind {
        BindingKind::LambdaArg => Color::Cyan,
        BindingKind::LambdaPatternEntry | BindingKind::LambdaPatternBind => Color::Magenta,
        BindingKind::LetBinding => Color::Red,
    }
}

fn print_stdout(s: &str) {
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    lock.write_all(s.as_bytes()).unwrap();
    lock.flush().unwrap();
}

/// Process one file. Returns whether dead code was found.
fn process_file(path: &Path, options: &Options) -> bool {
    let file_name = path.to_string_lossy().into_owned();
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Error reading file {}: {}", file_name, e);
            return false;
        }
    };

    let parsed = parser::parse(&content);
    if !parsed.errors.is_empty() {
        match options.output_format {
            OutputFormat::Json => {
                let results: Vec<JsonResult> = parsed
                    .errors
                    .iter()
                    .map(|e| JsonResult {
                        position: None,
                        message: e.to_string(),
                    })
                    .collect();
                print_stdout(&report::render_json(&file_name, &results));
            }
            OutputFormat::HumanReadable => {
                for e in &parsed.errors {
                    eprintln!("Error parsing file {}: {}", file_name, e);
                }
            }
        }
        return false;
    }

    let tree = &parsed.tree;
    let dead: Vec<DeadCode> = dead::find_dead_code(tree, &options.settings);
    if dead.is_empty() {
        return false;
    }

    if !options.quiet {
        match options.output_format {
            OutputFormat::Json => {
                let results: Vec<JsonResult> = dead
                    .iter()
                    .map(|d| {
                        let (s, e) = d.range(tree);
                        let (line, column) = report::line_col(&content, s);
                        let (_, end_column) = report::line_col(&content, e);
                        JsonResult {
                            position: Some((line, column, end_column)),
                            message: d.message(tree),
                        }
                    })
                    .collect();
                print_stdout(&report::render_json(&file_name, &results));
            }
            OutputFormat::HumanReadable => {
                let labels: Vec<Label> = dead
                    .iter()
                    .map(|d| {
                        let (s, e) = d.range(tree);
                        Label {
                            start: s,
                            end: e,
                            message: d.message(tree),
                            color: label_color(d.binding.kind),
                        }
                    })
                    .collect();
                let location = dead.first().map(|d| d.range(tree).0).unwrap_or(0);
                let out = report::render_human(
                    &file_name,
                    &content,
                    "Unused declarations were found.",
                    &labels,
                    location,
                    options.color,
                );
                print_stdout(&out);
            }
        }
    }

    if options.edit {
        let edits = edit::edits_for(tree, &dead);
        let new_content = edit::apply_edits(&content, edits);
        fs::write(path, new_content).expect("fs::write");
    }

    true
}
