rec {
  foldr = op: nul: list:
    let
      len = builtins.length list;
      fold' = n:
        if n == len
        then nul
        else op (builtins.elemAt list n) (fold' (n + 1));
    in fold' 0;

  foldl = op: nul: list:
    let
      foldl' = n:
        if n == -1
        then nul
        else op (foldl' (n - 1)) (builtins.elemAt list n);
    in foldl' (builtins.length list - 1);

  imap0 = f: list: lib.genList (n: f n (builtins.elemAt list n)) (builtins.length list);

  zipListsWith = f: fst: snd:
    lib.genList (n: f (builtins.elemAt fst n) (builtins.elemAt snd n)) (lib.min (builtins.length fst) (builtins.length snd));

  unusedTopLevelIsFine = x: x;

  partition = pred: lib.foldr (h: t:
    if pred h
    then { right = [h] ++ t.right; wrong = t.wrong; }
    else { right = t.right; wrong = [h] ++ t.wrong; }
  ) { right = []; wrong = []; };

  groupBy' = op: nul: pred: lst: lib.mapAttrs (name: lib.foldl op nul) (lib.groupBy pred lst);

  toposort = before: list:
    let
      dfs = lib.listDfs true before list;
      unusedInside = dfs;
    in
      if dfs ? cycle
      then { cycle = lib.reverseList ([ dfs.cycle ] ++ dfs.visited); inherit (dfs) loops; }
      else if lib.length list < 2 then { result = list; }
      else let
        toposorted = toposort before dfs.rest;
      in { result = toposorted.result ++ [ dfs.minimal ]; };
}
EOF
