{"command":"cd /workspace && cat > src/usage.rs <<'EOF'
//! Searching for usages of identifiers.

use crate::kinds::SyntaxKind::*;
use crate::scope::{inherit_from, may_be_scope, Scope};
use crate::tree::{NodeId, Tree};

/// Does `node` (or any of its descendants) reference `name`, ignoring anything
/// inside `exclude` and respecting shadowing by inner scopes?
pub fn find_usage(tree: &Tree, name: &str, node: NodeId, exclude: Option<(usize, usize)>) -> bool {
    let n = tree.node(node);
    if let Some((s, e)) = exclude {
        // node fully inside the excluded range
        if n.start >= s && n.end <= e {
            return false;
        }
    }
    match n.kind {
        NODE_IDENT => tree.ident_name(node) == name,
        NODE_ATTRPATH => tree
            .child_nodes(node)
            .filter(|c| tree.node(*c).kind != NODE_IDENT)
            .any(|c| find_usage(tree, name, c, exclude)),
        NODE_LET_IN => {
            // Inherits are evaluated in the surrounding scope: `inherit x;` refers to
            // the outer `x`, and `inherit (expr) ...` only uses `expr`.
            let shadowed = Scope::new(tree, node).map_or(false, |s| s.binds(tree, name));
            tree.child_nodes(node).any(|child| match tree.node(child).kind {
                NODE_INHERIT => find_usage_in_inherit(tree, name, child, exclude),
                _ => !shadowed && find_usage(tree, name, child, exclude),
            })
        }
        kind if may_be_scope(kind) => {
            match Scope::new(tree, node) {
                Some(scope) if scope.binds(tree, name) => {
                    // Shadowed. Only `inherit` entries directly in this scope may still
                    // refer to the outer binding.
                    tree.child_nodes(node)
                        .filter(|c| tree.node(*c).kind == NODE_INHERIT)
                        .any(|c| find_usage_in_inherit(tree, name, c, exclude))
                }
                _ => tree
                    .child_nodes(node)
                    .any(|c| find_usage(tree, name, c, exclude)),
            }
        }
        _ => tree
            .child_nodes(node)
            .any(|c| find_usage(tree, name, c, exclude)),
    }
}

/// Usages within an `inherit` statement: either in the `from` expression, or
/// (without `from`) in the inherited attribute names themselves.
fn find_usage_in_inherit(tree: &Tree, name: &str, inherit: NodeId, exclude: Option<(usize, usize)>) -> bool {
    match inherit_from(tree, inherit) {
        Some(from) => find_usage(tree, name, from, exclude),
        None => tree
            .child_nodes(inherit)
            .any(|attr| find_usage(tree, name, attr, exclude)),
    }
}
