start = s.index('fn remove_dead_entry')
end = s.index('fn is_empty_inherit')
new = '''/// Phase 1: collect edits removing dead bindings.
///
/// Every node is visited, even inside regions that are removed anyway; nested
/// edits are dropped when the edits are applied.
fn remove_dead(tree: &Tree, node: NodeId, dead_names: &HashSet<NodeId>, edits: &mut Vec<Edit>) {
    match tree.node(node).kind {
        NODE_ATTRPATH_VALUE => {
            if let Some(ident) = attrpath_value_ident(tree, node) {
                if dead_names.contains(&ident) {
                    let (s, e) = with_preceding_ws(tree, node);
                    edits.push((s, e, String::new()));
                }
            }
        }
        NODE_INHERIT => {
            for child in tree.child_nodes(node) {
                if tree.node(child).kind == NODE_IDENT && dead_names.contains(&child) {
                    let (s, e) = with_preceding_ws(tree, child);
                    edits.push((s, e, String::new()));
                }
            }
        }
        NODE_LAMBDA => {
            if let (Some(param), _) = lambda_parts(tree, node) {
                if tree.node(param).kind == NODE_IDENT && dead_names.contains(&param) {
                    let n = tree.node(param);
                    edits.push((n.start, n.end, format!("_{}", tree.ident_name(param))));
                }
            }
        }
        NODE_PAT_ENTRY | NODE_PAT_BIND => {
            let ident = tree
                .child_nodes(node)
                .find(|n| tree.node(*n).kind == NODE_IDENT);
            if let Some(ident) = ident {
                if dead_names.contains(&ident) {
                    if tree.node(node).kind == NODE_PAT_ENTRY {
                        edits.push(pat_entry_edit(tree, node));
                    } else {
                        edits.push(pat_bind_edit(tree, node));
                    }
                }
            }
        }
        _ => {}
    }
    for child in tree.child_nodes(node) {
        remove_dead(tree, child, dead_names, edits);
    }
}

